import{_ as e,o as i,c as r,a4 as t}from"./chunks/framework.LtCATpF9.js";const p=JSON.parse('{"title":"計算機の使い方","description":"Anno 117生産チェーン計算機の基本操作方法を解説。商品選択・生産チェーン表示・数量調整と、水道橋・アイテム・穀物庫などの補正の入れ方を説明。","frontmatter":{"title":"計算機の使い方","description":"Anno 117生産チェーン計算機の基本操作方法を解説。商品選択・生産チェーン表示・数量調整と、水道橋・アイテム・穀物庫などの補正の入れ方を説明。"},"headers":[],"relativePath":"guide/calculator-guide.md","filePath":"guide/calculator-guide.md"}'),l={name:"guide/calculator-guide.md"};function o(n,a,h,s,d,u){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="計算機の使い方" tabindex="-1">計算機の使い方 <a class="header-anchor" href="#計算機の使い方" aria-label="Permalink to &quot;計算機の使い方&quot;">​</a></h1><p>Anno 117 生産チェーン計算機の基本的な操作方法を説明します。</p><h2 id="基本的な流れ" tabindex="-1">基本的な流れ <a class="header-anchor" href="#基本的な流れ" aria-label="Permalink to &quot;基本的な流れ&quot;">​</a></h2><h3 id="_1-商品を選ぶ" tabindex="-1">1. 商品を選ぶ <a class="header-anchor" href="#_1-商品を選ぶ" aria-label="Permalink to &quot;1. 商品を選ぶ&quot;">​</a></h3><p>画面左のパネルにカテゴリ別の商品ツリーが表示されています。目的の商品をクリックすると、その商品の生産チェーンが中央パネルに表示されます。</p><h3 id="_2-生産チェーンを確認する" tabindex="-1">2. 生産チェーンを確認する <a class="header-anchor" href="#_2-生産チェーンを確認する" aria-label="Permalink to &quot;2. 生産チェーンを確認する&quot;">​</a></h3><p>中央パネルには、選択した商品を生産するために必要な建物と依存関係がグラフで表示されます。各ノードには建物名・必要件数が表示されます。</p><p>グラフの操作：</p><ul><li><strong>移動</strong>（デスクトップ）: 左クリックしたままドラッグ</li><li><strong>移動</strong>（タッチ）: 1本指でドラッグ</li><li><strong>拡大縮小</strong>（デスクトップ）: マウスホイール</li><li><strong>拡大縮小</strong>（タッチ）: 2本指でピンチ</li></ul><h3 id="_3-数量を調整する" tabindex="-1">3. 数量を調整する <a class="header-anchor" href="#_3-数量を調整する" aria-label="Permalink to &quot;3. 数量を調整する&quot;">​</a></h3><p>画面右のパネルで生産量の倍率を調整できます。目標とする生産数に合わせて必要な建物数が再計算されます。</p><h3 id="_4-生産性の補正を入れる" tabindex="-1">4. 生産性の補正を入れる <a class="header-anchor" href="#_4-生産性の補正を入れる" aria-label="Permalink to &quot;4. 生産性の補正を入れる&quot;">​</a></h3><p>画面右の「補正の設定」パネル（スマホは下の「補正」ボタン）で、生産性が上がる補正を選べます。選ぶとすぐ、必要な建物の軒数が再計算されます。</p><ul><li><strong>水道橋</strong>: 「水路灌漑（農場）」「森の飲み水（農園）」「水力採鉱法（鉱山）」の3つです。研究ごとに、1つずつ選べます。どれも生産性が +50% です。</li><li><strong>アイテム</strong>: 選んでいる商品に効く専門家のアイテムが並びます。選んだアイテムの分だけ、生産性が足されます。並ぶのは生産性が上がるアイテムだけで、維持費や労働力が減るアイテムなどは入っていません。</li></ul><h3 id="_5-ノードごとの補正" tabindex="-1">5. ノードごとの補正 <a class="header-anchor" href="#_5-ノードごとの補正" aria-label="Permalink to &quot;5. ノードごとの補正&quot;">​</a></h3><p>グラフのノードをクリックする（スマホはタップする）と、ポップアップが開きます。生産性・必要な建物数・建設費・維持費のほかに、「補正」の欄があります。</p><ul><li><strong>穀物庫</strong>: アイギュプトの農場など、穀物庫の範囲効果を受ける建物のノードにだけ出ます。「なし」「穀物庫（+15%）」「大型穀物庫（+25%）」「広大な穀物庫（+35%）」から選びます。穀物庫の効果は範囲内の建物にだけ掛かるので、その農場が範囲内にあるかどうかは、自分で選んでください。大型と広大の値はゲームデータのもので、実機での確認は未確認です。</li><li><strong>生産性を足す（%）</strong>: どのノードにも出ます。一覧にない補正や、ゲーム内で見た値を、そのまま足し算で入れられます（-100〜1000）。Enter を押すか、入力欄から離れると反映されます。</li></ul><p>補正が効いているノードは、角にアイコン（水道橋・穀物庫・アイテム）が重なります。2個まで並び、それより多いときは「+2」のように残りの数が出ます。木炭などの燃料を使う施設は、木炭が右下、補正が左下に出ます。</p><h2 id="その他の機能" tabindex="-1">その他の機能 <a class="header-anchor" href="#その他の機能" aria-label="Permalink to &quot;その他の機能&quot;">​</a></h2><h3 id="地域切り替え" tabindex="-1">地域切り替え <a class="header-anchor" href="#地域切り替え" aria-label="Permalink to &quot;地域切り替え&quot;">​</a></h3><p>ヘッダーの地域ボタンから <strong>ラティウム / アルビオン / アイギュプト（Aegyptus）</strong> を切り替えられます（ボタンを押すたびに順番に切り替わります）。各地域固有の商品や建物が反映されます。</p><h3 id="アイギュプトを選んだとき" tabindex="-1">アイギュプトを選んだとき <a class="header-anchor" href="#アイギュプトを選んだとき" aria-label="Permalink to &quot;アイギュプトを選んだとき&quot;">​</a></h3><ul><li>アイギュプトだけの商品のうち、生産チェーンのある18点を計算できます。数値はアップデート3.0のゲーム内データです。</li><li>石炭や金鉱石は、作れる建物が2種類あります。そのため、コールと象牙の小箱は「コール（炭焼き師）」「コール（炭鉱）」「象牙の小箱（金選鉱）」「象牙の小箱（金鉱）」のように、建物ごとに別のチェーンになっています。図の素材名にも「金鉱石（金選鉱）」のように建物名が付くので、どちらの建物で作る場合かを見分けられます。</li><li>ラティウム・アルビオンと共通の商品のうち、装甲・パン・チーズ・モザイク・サンダル・石鹸・瓦は、アイギュプトの建物で作るチェーンで計算できます。それ以外の共通の商品は、まだ対応していません。</li></ul><h3 id="言語切り替え" tabindex="-1">言語切り替え <a class="header-anchor" href="#言語切り替え" aria-label="Permalink to &quot;言語切り替え&quot;">​</a></h3><p>ヘッダーの「EN / 日本語」ボタンで表示言語を切り替えられます。</p><h3 id="建設コスト・維持費" tabindex="-1">建設コスト・維持費 <a class="header-anchor" href="#建設コスト・維持費" aria-label="Permalink to &quot;建設コスト・維持費&quot;">​</a></h3><p>画面下部に、選択中の生産チェーン全体の建設コストと維持費の合計が表示されます。</p><h2 id="wikiへ戻る" tabindex="-1">Wikiへ戻る <a class="header-anchor" href="#wikiへ戻る" aria-label="Permalink to &quot;Wikiへ戻る&quot;">​</a></h2><p>ヘッダー右上の「Wiki」リンクから Wiki トップへ戻ることができます。また、Wiki の生産チェーン・全商品一覧ページにある「開く」ボタンから、対応する商品を選択した状態で計算機を開けます。</p>',29)])])}const _=e(l,[["render",o]]);export{p as __pageData,_ as default};
